insert into public.steamh_projects (
  student_id,
  student_name,
  school_name,
  grade,
  subject,
  title,
  summary,
  description,
  challenge,
  solution,
  tools_used,
  tags,
  image_urls,
  video_urls,
  attachment_urls,
  external_links,
  published,
  created_at,
  updated_at
)
select
  null as student_id,
  'The Oakland Toy Lab' as student_name,
  'Instructables Educator Collection' as school_name,
  '6-10' as grade,
  'STEAM Activity' as subject,
  source_titles.title,
  format('Classroom STEAM activity #%s from the Instructables educator collection.', source_titles.idx),
  format(
    'Curated from the "100 STEAM Projects for Educators" list on Instructables. Activity: %s',
    source_titles.title
  ),
  null as challenge,
  null as solution,
  '{}'::text[] as tools_used,
  array['instructables', 'steam', 'classroom']::text[] as tags,
  jsonb_build_array(source_titles.cover_url) as image_urls,
  '[]'::jsonb as video_urls,
  '[]'::jsonb as attachment_urls,
  jsonb_build_array(
    jsonb_build_object(
      'label', 'Activity Page',
      'url', source_titles.activity_url
    ),
    jsonb_build_object(
      'label', 'Source Collection',
      'url', 'https://www.instructables.com/100-STEAM-Projects-for-Educators/'
    )
  ) as external_links,
  true as published,
  now() - ((101 - source_titles.idx)::text || ' days')::interval as created_at,
  now() - ((101 - source_titles.idx)::text || ' days')::interval as updated_at
from source_titles
where not exists (
  select 1
  from public.steamh_projects existing
  where lower(existing.title) = lower(source_titles.title)
);

