update public.steamh_projects as projects
set
  image_urls = jsonb_build_array(source_titles.cover_url),
  external_links = jsonb_build_array(
    jsonb_build_object(
      'label', 'Activity Page',
      'url', source_titles.activity_url
    ),
    jsonb_build_object(
      'label', 'Source Collection',
      'url', 'https://www.instructables.com/100-STEAM-Projects-for-Educators/'
    )
  ),
  updated_at = now()
from source_titles
where lower(projects.title) = lower(source_titles.title);

notify pgrst, 'reload schema';
